package com.ias.ticket;

import com.ias.trust.*;
import jakarta.servlet.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.sql.Timestamp;
import java.security.*;
import java.util.*;

@RestController
public class Tickets {
 final JdbcTemplate db;final TransactionTemplate tx;final StaffAccess staff=new StaffAccess();
 public Tickets(JdbcTemplate db,TransactionTemplate tx){this.db=db;this.tx=tx;}
 record Actor(long tenant,long user,String type,String token,String csrf,String trace,long deadline,String attempt){@Override public String toString(){return "TicketActor[redacted]";}}
 static Problem bad(){return new Problem(400,"VALIDATION_ERROR");}
 static long id(Object o){try{long v=Long.parseLong(o.toString());if(v<1)throw bad();return v;}catch(Exception e){throw bad();}}
 static long idOrZero(Object o){try{long n=Long.parseLong(o.toString());if(n<0)throw bad();return n;}catch(Exception e){throw bad();}}
 static String uuid(Object o){try{String s=o.toString();if(!UUID.fromString(s).toString().equals(s))throw bad();return s;}catch(Exception e){throw bad();}}
 static String text(Object o,int min,int max,boolean multiline){if(!(o instanceof String s)||s.codePointCount(0,s.length())<min||s.codePointCount(0,s.length())>max)throw bad();if(min>0&&s.isBlank())throw bad();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(Character.isHighSurrogate(c)){if(++i>=s.length()||!Character.isLowSurrogate(s.charAt(i)))throw bad();}else if(Character.isLowSurrogate(c)||Character.isISOControl(c)&&!(multiline&&"\n\r\t".indexOf(c)>=0))throw bad();}return s;}
 static String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Chain.JSON.writeValueAsBytes(value)));}catch(Exception e){throw new IllegalStateException();}}
 static Map<String,Object> json(Object o){return Chain.JSON.readValue(o.toString(),Map.class);}
 static String utc(Object v){return v instanceof Timestamp ts?ts.toInstant().toString():v instanceof LocalDateTime dt?dt.toInstant(ZoneOffset.UTC).toString():v.toString();}
 Actor actor(HttpServletRequest r,boolean write){if(write)Chain.source(r);long deadline=Chain.deadline(r);String token=Chain.cookie(r),csrf=r.getHeader("X-CSRF-TOKEN");var a=Chain.identity("ticket-identity",token,write?"TICKET_CREATE":"TICKET_READ",csrf,Chain.trace(r),deadline);Chain.fresh(a,deadline);return new Actor(id(a.get("tenantId")),id(a.get("userId")),a.get("identityType").toString(),token,csrf,Chain.trace(r),deadline,a.get("attempt").toString());}
 void fresh(Actor a){Chain.fresh(Chain.identity("ticket-identity",a.token,"TICKET_CREATE",a.csrf,a.trace,a.deadline),a.deadline);}
 Map<String,Object> delegate(Actor a){var b=new HashMap<String,Object>();b.put("sessionToken",a.token);b.put("csrfToken",a.csrf);return b;}
 List<String> companies(Actor a){var b=delegate(a);var out=Chain.call("ticket-asset","/internal/asset/repair-access",b,a.trace,a.deadline);Chain.fresh(out,a.deadline);return (List<String>)out.get("companyIds");}
 void device(Actor a,Object device,Object version,boolean create){var b=delegate(a);b.put("deviceId",device);b.put("expectedOwnershipVersion",version);b.put("newBusiness",create);Chain.fresh(Chain.call("ticket-asset","/internal/asset/repair-access",b,a.trace,a.deadline),a.deadline);}
 Map<String,Object> op(String key,Actor a){var rows=db.queryForList("SELECT * FROM ticket_create_operation WHERE operation_id=? AND tenant_id=? AND actor_user_id=?",uuid(key),a.tenant,a.user);if(rows.isEmpty())throw new Problem(404,"OPERATION_NOT_FOUND");var o=rows.getFirst();if(o.get("binding_json")!=null){var s=json(o.get("binding_json"));var snapshot=(Map<String,Object>)s.get("snapshot");var company=(Map<String,Object>)snapshot.get("companySnapshot");if(!companies(a).contains(company.get("id")))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");}else device(a,o.get("device_id").toString(),null,false);return o;}
 Map<String,Object> input(Map<String,Object>b){
  var fields=Set.of("deviceId","expectedOwnershipVersion","title","description","categoryCode","impact","contactName","contactPhone","attachmentIds","duplicateAcknowledged");if(!fields.containsAll(b.keySet())||!b.keySet().containsAll(Set.of("deviceId","expectedOwnershipVersion","title","description","impact","contactName","contactPhone","attachmentIds","duplicateAcknowledged")))throw bad();
  if(!(b.get("deviceId") instanceof String)||!(b.get("expectedOwnershipVersion") instanceof String))throw bad();var o=new TreeMap<String,Object>();o.put("deviceId",Long.toString(id(b.get("deviceId"))));o.put("expectedOwnershipVersion",Long.toString(id(b.get("expectedOwnershipVersion"))));o.put("title",text(b.get("title"),5,100,false));o.put("description",text(b.get("description"),20,5000,true));o.put("contactName",text(b.get("contactName"),1,50,false));String phone=text(b.get("contactPhone"),1,30,false);if(!phone.matches("[0-9 +()xX分机-]+")||!phone.matches(".*[0-9].*"))throw bad();o.put("contactPhone",phone);String category=b.get("categoryCode")==null?"UNCERTAIN":b.get("categoryCode").toString();if(!category.equals("UNCERTAIN")||!Set.of("UNUSABLE","AFFECTED","CONSULTATION").contains(b.get("impact")))throw bad();o.put("categoryCode",category);o.put("impact",b.get("impact"));if(!(b.get("duplicateAcknowledged") instanceof Boolean))throw bad();o.put("duplicateAcknowledged",b.get("duplicateAcknowledged"));if(!(b.get("attachmentIds") instanceof List<?> list)||list.size()>5)throw bad();var files=list.stream().map(Tickets::uuid).sorted().toList();if(new HashSet<>(files).size()!=files.size())throw bad();o.put("attachmentIds",files);return o;
 }
 @PostMapping("/api/ticket/tickets") ResponseEntity<?> create(@RequestBody Map<String,Object>b,HttpServletRequest r){Actor a=actor(r,true);var data=input(b);String key=uuid(Chain.single(r,"Idempotency-Key")),digest=hash(data);boolean[] existing={false};
  if(db.queryForObject("SELECT COUNT(*) FROM ticket_create_operation WHERE operation_id=?",Long.class,key)==0)device(a,data.get("deviceId"),data.get("expectedOwnershipVersion"),true);else op(key,a);
  tx.executeWithoutResult(t->{lockActor(a.tenant,a.user);var rows=db.queryForList("SELECT * FROM ticket_create_operation WHERE operation_id=? FOR UPDATE",key);if(!rows.isEmpty()){var o=rows.getFirst();if(id(o.get("tenant_id"))!=a.tenant||id(o.get("actor_user_id"))!=a.user)throw new Problem(404,"OPERATION_NOT_FOUND");if(!o.get("request_digest").equals(digest))throw new Problem(409,"IDEMPOTENCY_CONFLICT");existing[0]=true;return;}db.update("INSERT INTO ticket_create_operation(operation_id,binding_id,ticket_id,tenant_id,actor_user_id,device_id,request_digest,input_json,state,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,'REGISTERED',UTC_TIMESTAMP(3),UTC_TIMESTAMP(3))",key,UUID.randomUUID().toString(),UUID.randomUUID().toString(),a.tenant,a.user,id(data.get("deviceId")),digest,Chain.JSON.writeValueAsString(data));});
  return advanceResponse(key,a,!existing[0]);
 }
 void lockActor(long tenant,long user){db.update("INSERT INTO ticket_actor_lock(tenant_id,user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE user_id=ticket_actor_lock.user_id",tenant,user);db.queryForMap("SELECT * FROM ticket_actor_lock WHERE tenant_id=? AND user_id=? FOR UPDATE",tenant,user);}
 @GetMapping("/api/ticket/create-operations/{key}") Map<String,Object> operation(@PathVariable String key,HttpServletRequest r){return view(op(key,actor(r,false)));}
 @PostMapping("/api/ticket/create-operations/{key}/resume") ResponseEntity<?> resume(@PathVariable String key,@RequestBody Map<String,Object>b,HttpServletRequest r){if(!b.isEmpty())throw bad();Actor a=actor(r,true);op(key,a);return advanceResponse(key,a,false);}
 ResponseEntity<?> advanceResponse(String key,Actor a,boolean created){try{var o=advance(key,a);if(o.get("state").equals("COMPLETED"))return ResponseEntity.status(created?201:200).body(result(o));if(o.get("state").equals("ABORTED"))return ResponseEntity.status(409).body(view(o));return ResponseEntity.status(202).body(view(o));}catch(Exception error){try{var rows=db.queryForList("SELECT * FROM ticket_create_operation WHERE operation_id=? AND tenant_id=? AND actor_user_id=?",key,a.tenant,a.user);if(!rows.isEmpty()&&rows.getFirst().get("state").equals("COMMITTED"))return ResponseEntity.status(202).body(view(rows.getFirst()));}catch(Exception ignored){}return ResponseEntity.status(error instanceof Problem p?p.status:503).body(Map.of("code",error instanceof Problem p?p.code:"OPERATION_RESULT_UNKNOWN","operationId",key,"traceId",a.trace,"nextAction","RESUME"));}}
 Map<String,Object> request(Map<String,Object> o){return new HashMap<>(Map.of("operationId",o.get("operation_id"),"bindingId",o.get("binding_id"),"ticketId",o.get("ticket_id"),"requestDigest",o.get("request_digest")));}
 Map<String,Object> advance(String key,Actor a){
  var before=op(key,a);if(Set.of("COMPLETED","ABORTED").contains(before.get("state")))return before;if(before.get("state").equals("COMMITTED")){confirm(before,a.trace,a.deadline);return op(key,a);}
  List<String> accessibleCompanies=companies(a);String lease=UUID.randomUUID().toString();tx.executeWithoutResult(t->{lockActor(a.tenant,a.user);var o=db.queryForMap("SELECT * FROM ticket_create_operation WHERE operation_id=? FOR UPDATE",key);if(!Set.of("REGISTERED","RESERVED").contains(o.get("state")))throw new Problem(409,"OPERATION_BUSY");if(db.queryForObject("SELECT COUNT(*) FROM ticket_create_operation WHERE tenant_id=? AND actor_user_id=? AND lease_until>UTC_TIMESTAMP(3)",Long.class,a.tenant,a.user)>0)throw new Problem(409,"OPERATION_BUSY");var in=json(o.get("input_json"));
   var duplicateArgs=new ArrayList<Object>(List.of(a.tenant,a.user,o.get("device_id")));accessibleCompanies.forEach(c->duplicateArgs.add(id(c)));
   if(!Boolean.TRUE.equals(in.get("duplicateAcknowledged"))&&!accessibleCompanies.isEmpty()&&db.queryForObject("SELECT COUNT(*) FROM ticket_record WHERE tenant_id=? AND reporter_user_id=? AND device_id=? AND company_id IN ("+String.join(",",Collections.nCopies(accessibleCompanies.size(),"?"))+")",Long.class,duplicateArgs.toArray())>0){db.update("UPDATE ticket_create_operation SET state='ABORTED',reason='DUPLICATE_CONFIRMATION_REQUIRED',row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE operation_id=?",key);audit(o,"CREATE_ABORTED");return;}
   db.update("UPDATE ticket_create_operation SET lease_id=?,lease_until=TIMESTAMPADD(SECOND,10,UTC_TIMESTAMP(3)),row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE operation_id=?",lease,key);
  });
  var o=op(key,a);if(o.get("state").equals("ABORTED")){release(o,a.trace,a.deadline);return o;}
  try{
   var in=json(o.get("input_json"));var req=request(o);req.putAll(delegate(a));req.put("deviceId",in.get("deviceId"));req.put("expectedOwnershipVersion",in.get("expectedOwnershipVersion"));
   var binding=Chain.call("ticket-asset","/internal/asset/repair-bindings/reserve",req,a.trace,a.deadline);
   if(!Objects.equals(binding.get("bindingId"),o.get("binding_id"))||!Set.of("RESERVED","CONFIRMED").contains(binding.get("state")))throw new Problem(503,"DEPENDENCY_UNAVAILABLE");
   tx.executeWithoutResult(t->{var locked=lockLease(key,lease);if(!Set.of("REGISTERED","RESERVED").contains(locked.get("state")))throw new Problem(409,"OPERATION_ABORTED");db.update("UPDATE ticket_create_operation SET state='RESERVED',binding_json=?,row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE operation_id=?",Chain.JSON.writeValueAsString(binding),key);});
   tx.executeWithoutResult(t->{lockActor(a.tenant,a.user);var locked=lockLease(key,lease);if(!locked.get("state").equals("RESERVED"))throw new Problem(409,"OPERATION_ABORTED");fresh(a);var snapshot=(Map<String,Object>)binding.get("snapshot");var company=(Map<String,Object>)snapshot.get("companySnapshot");String ticket=locked.get("ticket_id").toString();
    db.update("INSERT INTO ticket_record(id,ticket_no,operation_id,tenant_id,reporter_user_id,company_id,device_id,title,description,category_code,impact,contact_name,contact_phone,snapshot_json,submitted_at,created_at,round_id,initial_priority,priority,response_due_at,resolution_due_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(3),'00000000-0000-0000-0000-000000000000','P3','P3',UTC_TIMESTAMP(3),UTC_TIMESTAMP(3))",ticket,"T"+ticket.replace("-","").toUpperCase(Locale.ROOT),key,a.tenant,a.user,id(company.get("id")),locked.get("device_id"),in.get("title"),in.get("description"),in.get("categoryCode"),in.get("impact"),in.get("contactName"),in.get("contactPhone"),Chain.JSON.writeValueAsString(snapshot),Timestamp.from(Instant.parse(binding.get("acceptedAt").toString())));
    String initial=Workflow.initial(in.get("impact"));db.update("UPDATE ticket_record SET round_id=id,initial_priority=?,priority=?,response_due_at=TIMESTAMPADD(MINUTE,?,submitted_at),resolution_due_at=TIMESTAMPADD(HOUR,?,submitted_at) WHERE id=?",initial,initial,Workflow.responseMinutes(initial),Workflow.resolutionHours(initial),ticket);
    new Rounds(this).initial(ticket);
    db.update("INSERT INTO ticket_sla_target_history(ticket_id,round_id,new_priority,submitted_at,response_due_at,resolution_due_at,policy_version,created_at) SELECT id,round_id,priority,round_started_at,response_due_at,resolution_due_at,policy_version,UTC_TIMESTAMP(3) FROM ticket_record WHERE id=?",ticket);
    for(String file:new TreeSet<>((List<String>)in.get("attachmentIds"))){var rows=db.queryForList("SELECT * FROM ticket_file WHERE id=? FOR UPDATE",file);if(rows.isEmpty())throw new Problem(409,"INVALID_FILE");var f=rows.getFirst();if(SupplementFiles.isSupplement(f)||!f.get("state").equals("READY")||id(f.get("tenant_id"))!=a.tenant||id(f.get("user_id"))!=a.user||!f.get("submission_id").equals(key)||db.queryForObject("SELECT COUNT(*) FROM ticket_file_reference WHERE file_id=?",Long.class,file)>0)throw new Problem(409,"INVALID_FILE");db.update("INSERT INTO ticket_file_reference(file_id,ticket_id) VALUES(?,?)",file,ticket);}
    Chain.remaining(a.deadline);db.update("UPDATE ticket_create_operation SET state='COMMITTED',reason=NULL,lease_id=NULL,lease_until=NULL,row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE operation_id=?",key);audit(locked,"TICKET_SUBMITTED");
   });
   o=op(key,a);confirm(o,a.trace,a.deadline);return op(key,a);
  }finally{db.update("UPDATE ticket_create_operation SET lease_id=NULL,lease_until=NULL WHERE operation_id=? AND lease_id=?",key,lease);}
 }
 Map<String,Object> lockLease(String key,String lease){var o=db.queryForMap("SELECT *,lease_until>UTC_TIMESTAMP(3) lease_valid FROM ticket_create_operation WHERE operation_id=? FOR UPDATE",key);if(!lease.equals(o.get("lease_id"))||!Boolean.TRUE.equals(o.get("lease_valid"))&&!(o.get("lease_valid") instanceof Number n&&n.intValue()==1))throw new Problem(409,"OPERATION_ABORTED");return o;}
 void confirm(Map<String,Object>o,String trace,long deadline){Chain.call("ticket-asset","/internal/asset/repair-bindings/"+o.get("binding_id")+"/confirm",request(o),trace,deadline);tx.executeWithoutResult(t->{if(db.update("UPDATE ticket_create_operation SET state='COMPLETED',row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE operation_id=? AND state='COMMITTED'",o.get("operation_id"))==1)audit(o,"BINDING_CONFIRMED");});}
 void release(Map<String,Object>o,String trace,long deadline){Chain.call("ticket-asset","/internal/asset/repair-bindings/"+o.get("binding_id")+"/release",request(o),trace,deadline);}
 void audit(Map<String,Object>o,String action){db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,?,UTC_TIMESTAMP(3))",o.get("operation_id"),o.get("tenant_id"),o.get("actor_user_id"),action);}
 Map<String,Object> result(Map<String,Object>o){var row=db.queryForMap("SELECT * FROM ticket_record WHERE operation_id=?",o.get("operation_id"));return Map.of("operationId",o.get("operation_id"),"ticketId",row.get("id"),"ticketNo",row.get("ticket_no"),"status",row.get("status"),"rowVersion",row.get("row_version").toString(),"submittedAt",utc(row.get("submitted_at")),"nextAction","VIEW_TICKET");}
 Map<String,Object> view(Map<String,Object>o){var out=new LinkedHashMap<String,Object>();String state=o.get("state").toString();out.put("operationId",o.get("operation_id"));out.put("state",state);out.put("nextAction",state.equals("COMPLETED")?"VIEW_TICKET":state.equals("ABORTED")?"NONE":"RESUME");out.put("reason",state.equals("COMMITTED")?"BINDING_CONFIRM_PENDING":o.get("reason"));if(state.equals("ABORTED"))out.put("code",o.get("reason")==null?"OPERATION_ABORTED":o.get("reason"));out.put("ticket",Set.of("COMMITTED","COMPLETED").contains(state)?result(o):null);return out;}
 @PostMapping("/internal/ticket/create-facts/{key}") Map<String,Object> facts(@PathVariable String key,@RequestBody Map<String,Object>b){var rows=db.queryForList("SELECT * FROM ticket_create_operation WHERE operation_id=?",uuid(key));if(rows.isEmpty())return Map.of("state","ABSENT");var o=rows.getFirst();for(String[] pair:new String[][]{{"bindingId","binding_id"},{"ticketId","ticket_id"},{"requestDigest","request_digest"}})if(!Objects.equals(b.get(pair[0]),o.get(pair[1])))throw new Problem(409,"IDEMPOTENCY_CONFLICT");return Map.of("state",o.get("state"),"tenantId",o.get("tenant_id").toString(),"actorUserId",o.get("actor_user_id").toString(),"deviceId",o.get("device_id").toString());}
 String scope(Actor a,List<Object>args){args.add(a.tenant);String where="r.tenant_id=? AND EXISTS(SELECT 1 FROM ticket_create_operation o WHERE o.operation_id=r.operation_id AND o.state='COMPLETED')";List<String> companies=a.type.equals("CUSTOMER")?companies(a):List.of();if(!a.type.equals("CUSTOMER"))where+=" AND "+staff.sql(a,args);if(a.type.equals("CUSTOMER")){args.add(a.user);where+=" AND r.reporter_user_id=?";if(companies.isEmpty())where+=" AND 1=0";else{where+=" AND r.company_id IN ("+String.join(",",Collections.nCopies(companies.size(),"?"))+")";companies.forEach(c->args.add(id(c)));}}return where;}
 Map<String,Object> accessible(String key,Actor a){var args=new ArrayList<Object>();String where=scope(a,args);args.add(uuid(key));var rows=db.queryForList("SELECT r.* FROM ticket_record r WHERE "+where+" AND r.id=?",args.toArray());if(rows.isEmpty())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");return rows.getFirst();}
 Map<String,Object> summary(Map<String,Object>row){var out=new LinkedHashMap<String,Object>();for(String[] p:new String[][]{{"id","id"},{"ticketNo","ticket_no"},{"title","title"},{"status","status"}})out.put(p[0],row.get(p[1]));out.put("roundId",row.get("round_id"));out.put("priority",row.get("priority"));out.put("rowVersion",row.get("row_version").toString());out.put("submittedAt",utc(row.get("submitted_at")));out.putAll(json(row.get("snapshot_json")));return out;}
 @GetMapping("/api/ticket/tickets/{key}") Map<String,Object> detail(@PathVariable String key,HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw bad();var a=actor(r,false);return detailView(accessible(key,a),a);}
 Map<String,Object> detailView(Map<String,Object>row,Actor a){String key=row.get("id").toString();var out=summary(row);for(String[] p:new String[][]{{"description","description"},{"categoryCode","category_code"},{"impact","impact"},{"contactName","contact_name"},{"contactPhone","contact_phone"}})out.put(p[0],row.get(p[1]));out.put("reporterUserId",row.get("reporter_user_id").toString());addWorkflow(out,row,a);new Completion(this,staff).project(out,row,a);new Supplements(this,staff).project(out,row,a);new Cancellations(this,staff).project(out,row,a);new Transfers(this,staff).project(out,row,a);new Rounds(this).project(out,row,row.get("round_id"));new Reopens(this,staff).project(out,row,a);out.put("attachments",db.queryForList("SELECT f.* FROM ticket_file f JOIN ticket_file_reference x ON x.file_id=f.id WHERE x.ticket_id=? AND f.supplement_request_id IS NULL ORDER BY f.id",key).stream().map(FileStore::dto).toList());return out;}
 @GetMapping("/api/ticket/tickets") Map<String,Object> list(HttpServletRequest r){Actor a=actor(r,false);var args=new ArrayList<Object>();String where=scope(a,args);for(var p:r.getParameterMap().entrySet())if(!Set.of("keyword","deviceId","status","priority","departmentId","mine","from","to","page","size","coordination","cancellation","reopen").contains(p.getKey())||p.getValue().length!=1)throw bad();String keyword=r.getParameter("keyword");if(keyword!=null&&!keyword.isEmpty()){text(keyword,0,100,false);where+=" AND (r.title LIKE ? ESCAPE '!' OR r.ticket_no LIKE ? ESCAPE '!')";String q="%"+keyword.replace("!","!!").replace("%","!%").replace("_","!_")+"%";args.add(q);args.add(q);}if(r.getParameter("deviceId")!=null){where+=" AND r.device_id=?";args.add(id(r.getParameter("deviceId")));}for(String p:List.of("status","priority","departmentId"))if(r.getParameter(p)!=null){String value=r.getParameter(p);if(p.equals("status")&&!Set.of("PENDING_ACCEPTANCE","WAITING_ASSIGNMENT","REJECTED","ASSIGNED","IN_PROGRESS","WAITING_INFORMATION","PENDING_CUSTOMER_CONFIRMATION","RESOLVED","CLOSED","CANCELLED").contains(value)||p.equals("priority")&&!Set.of("P1","P2","P3").contains(value))throw bad();where+=" AND r."+(p.equals("departmentId")?"department_id":p)+"=?";args.add(p.equals("departmentId")?id(value):value);}if(r.getParameter("mine")!=null){if(!a.type.equals("EMPLOYEE")||!Set.of("ASSIGNED","IN_PROGRESS","WAITING_INFORMATION","PENDING_CUSTOMER_CONFIRMATION","RESOLVED","CLOSED","CANCELLED").contains(r.getParameter("mine")))throw bad();where+=" AND r.engineer_user_id=? AND r.status=?";args.add(a.user);args.add(r.getParameter("mine"));}if(r.getParameter("coordination")!=null){if(!a.type.equals("EMPLOYEE"))throw new Problem(403,"ACCESS_DENIED");if(!Set.of("CONFIRMATION_LIMIT_REACHED","SUPPLEMENT_LIMIT_REACHED","TRANSFER_REQUIRED").contains(r.getParameter("coordination")))throw bad();var f=staff.facts(a);if(!staff.permission(f,"ticket.read"))throw new Problem(403,"ACCESS_DENIED");var scoped=(List<?>)f.get("companyIds");if(scoped.isEmpty())where+=" AND 1=0";else{where+=" AND r.company_id IN ("+String.join(",",Collections.nCopies(scoped.size(),"?"))+")";scoped.forEach(c->args.add(id(c)));}if(!r.getParameter("coordination").equals("TRANSFER_REQUIRED")){where+=r.getParameter("coordination").equals("SUPPLEMENT_LIMIT_REACHED")?" AND r.status='WAITING_INFORMATION' AND (SELECT COALESCE(SUM(TIMESTAMPDIFF(MICROSECOND,s.requested_at,COALESCE(d.replied_at,?))),0) FROM ticket_supplement_request s LEFT JOIN ticket_supplement_reply d ON d.request_id=s.id WHERE s.ticket_id=r.id AND s.round_id=r.round_id)>=259200000000":" AND r.status='PENDING_CUSTOMER_CONFIRMATION' AND (SELECT COALESCE(SUM(TIMESTAMPDIFF(MICROSECOND,s.submitted_at,COALESCE(d.decided_at,?))),0) FROM ticket_solution s LEFT JOIN ticket_solution_decision d ON d.solution_id=s.id WHERE s.ticket_id=r.id AND s.round_id=r.round_id)>=259200000000";args.add(db.queryForObject("SELECT UTC_TIMESTAMP(3)",Timestamp.class));}}if(r.getParameter("cancellation")!=null){if(!"PENDING_REVIEW".equals(r.getParameter("cancellation")))throw bad();if(!a.type.equals("EMPLOYEE"))throw new Problem(403,"ACCESS_DENIED");var f=staff.facts(a);if(!staff.permission(f,"ticket.read")||!staff.permission(f,"ticket.cancel.review"))throw new Problem(403,"ACCESS_DENIED");var companies=(List<?>)f.get("companyIds");if(companies.isEmpty())where+=" AND 1=0";else{where+=" AND r.company_id IN ("+String.join(",",Collections.nCopies(companies.size(),"?"))+")";companies.forEach(c->args.add(id(c)));}where+=" AND r.current_cancel_request_id IS NOT NULL";}for(String p:List.of("from","to"))if(r.getParameter(p)!=null){where+=" AND r.submitted_at"+(p.equals("from")?">=":"<=")+"?";try{args.add(Timestamp.from(Instant.parse(r.getParameter(p))));}catch(Exception e){throw bad();}}long pageValue=r.getParameter("page")==null?1:id(r.getParameter("page")),sizeValue=r.getParameter("size")==null?20:id(r.getParameter("size"));if(pageValue>1000000||!Set.of(20L,50L,100L).contains(sizeValue))throw bad();int page=(int)pageValue,size=(int)sizeValue;if("TRANSFER_REQUIRED".equals(r.getParameter("coordination")))return new Transfers(this,staff).coordinationList(where,args,page,size,a);if(r.getParameter("reopen")!=null){if(!"PENDING_REVIEW".equals(r.getParameter("reopen")))throw bad();return new Reopens(this,staff).queue(where,args,a,page,size);}
  long total=db.queryForObject("SELECT COUNT(*) FROM ticket_record r WHERE "+where,Long.class,args.toArray());args.add(size);args.add((page-1L)*size);return Map.of("items",db.queryForList("SELECT r.* FROM ticket_record r WHERE "+where+" ORDER BY r.submitted_at DESC,r.id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(this::summary).toList(),"total",total,"page",page,"size",size);}
 @GetMapping("/api/ticket/duplicate-candidates") Map<String,Object> duplicates(HttpServletRequest r){Actor a=actor(r,false);if(!a.type.equals("CUSTOMER")||r.getParameterMap().size()!=1||r.getParameterValues("deviceId")==null||r.getParameterValues("deviceId").length!=1)throw bad();device(a,r.getParameter("deviceId"),null,false);var args=new ArrayList<Object>();String where=scope(a,args);args.add(id(r.getParameter("deviceId")));return Map.of("items",db.queryForList("SELECT r.* FROM ticket_record r WHERE "+where+" AND r.device_id=? ORDER BY r.submitted_at DESC,r.id DESC LIMIT 100",args.toArray()).stream().map(this::summary).toList());}
 void addWorkflow(Map<String,Object>out,Map<String,Object>row,Actor a){
  out.put("initialPriority",row.get("initial_priority"));out.put("priorityRuleVersion",row.get("priority_rule_version"));out.put("firstResponseAt",row.get("first_response_at")==null?null:utc(row.get("first_response_at")));out.put("firstResponseRecordId",row.get("first_response_record_id"));out.put("sla",Map.of("responseDueAt",utc(row.get("response_due_at")),"resolutionDueAt",utc(row.get("resolution_due_at")),"policyVersion",row.get("policy_version")));
  var records=db.queryForList("SELECT * FROM ticket_processing_record WHERE ticket_id=? AND round_id=?"+(a.type.equals("CUSTOMER")?" AND visibility='CUSTOMER_VISIBLE'":"")+" ORDER BY occurred_at,id LIMIT 100",row.get("id"),row.get("round_id"));var workflow=new Workflow(this,staff);var timeline=new ArrayList<Map<String,Object>>();timeline.add(Map.of("type",row.get("round_id").equals(row.get("id"))?"SUBMITTED":"ROUND_STARTED","at",Rounds.start(row).toString()));records.forEach(rec->timeline.add(workflow.recordView(rec,a.type.equals("CUSTOMER"))));out.put("timeline",timeline);out.put("allowedActions",List.of());
  if(!a.type.equals("EMPLOYEE"))return;var f=staff.facts(a);var actions=new ArrayList<String>();String state=row.get("status").toString();
  if(staff.company(f,row.get("company_id"))){if(state.equals("PENDING_ACCEPTANCE")){if(staff.permission(f,"ticket.accept"))actions.add("accept");if(staff.permission(f,"ticket.reject"))actions.add("reject");}if(state.equals("WAITING_ASSIGNMENT")&&staff.permission(f,"ticket.assign"))actions.add("assign");}
  String qualification="NONE";if(row.get("assignment_id")!=null){out.put("assignment",Map.of("assignmentId",row.get("assignment_id"),"departmentId",row.get("department_id").toString(),"engineerUserId",row.get("engineer_user_id").toString(),"state",state));if(staff.engineer(f,row)){qualification=staff.permission(f,"ticket.assignment.accept")&&staff.permission(f,"ticket.record")?"VALID":"INVALID";if(state.equals("ASSIGNED")&&staff.permission(f,"ticket.assignment.accept")&&staff.permission(f,"ticket.record"))actions.add("assignment-accept");if((state.equals("IN_PROGRESS")||state.equals("WAITING_INFORMATION")&&"IN_PROGRESS".equals(new Supplements(this,staff).current(row,false).get("resume_state")))&&staff.permission(f,"ticket.record"))actions.add("records");}else if(staff.company(f,row.get("company_id"))&&staff.permission(f,"ticket.assign")&&((List<?>)f.get("assignableDepartmentIds")).contains(row.get("department_id").toString())){qualification=staff.target(a,row.get("engineer_user_id"),row.get("department_id"))?"VALID":"INVALID";if(qualification.equals("INVALID")&&state.equals("ASSIGNED"))actions.add("release-invalid-assignment");}}
  out.put("qualificationStatus",qualification);out.put("allowedActions",actions);out.put("assignableDepartments",staff.company(f,row.get("company_id"))&&staff.permission(f,"ticket.assign")?f.get("assignableDepartments"):List.of());
 }
}





